#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=5

DRY=0
CLEAR=0
CONTROLLER_USER="claude"
WORKER_USER="commonroom-worker"
ALIAS="cr-space"
HOST="127.0.0.1"
BIN_DIR="/opt/commonroom-space/bin"
KEY_NAME="commonroom-controller"

while (( $# )); do
  case "$1" in
    --dry-run) DRY=1 ;;
    --clear) CLEAR=1 ;;
    --controller-user) shift; CONTROLLER_USER="${1:?name}" ;;
    --worker-user) shift; WORKER_USER="${1:?name}" ;;
    --alias) shift; ALIAS="${1:?name}" ;;
    -h|--help)
      printf 'Usage: %s [--dry-run] [--clear] [--controller-user NAME] [--worker-user NAME] [--alias NAME]\n' "$0"
      printf 'Lets the controller account reach the worker account over SSH through a forced-command gate.\n'
      printf 'Checks every item first, asks before replacing anything, and keeps backups. --dry-run changes nothing.\n'
      return 0 ;;
    *) printf 'Unknown argument: %s\n' "$1" >&2; return 2 ;;
  esac
  shift
done

if (( ! CLEAR )); then _clear() { :; }; fi
TMP=$(mktemp -d); trap 'rm -rf "$TMP"' EXIT
run() { if (( DRY )); then note "would run: $*"; else "$@"; fi; }
die() { warn "$1"; exit 1; }
as_controller() { if [[ "$(id -un)" == "$CONTROLLER_USER" ]]; then "$@"; else sudo -u "$CONTROLLER_USER" -H "$@"; fi; }

[[ "$ALIAS" =~ ^[A-Za-z0-9][A-Za-z0-9_.-]{0,63}$ ]] || die "Alias must match the controller's alias pattern."
[[ "$CONTROLLER_USER" != "$WORKER_USER" ]] || die "The controller and worker accounts must differ."

# ── Stage 1: inspect (read-only) ─────────────────────────────────────────
stage "Inspect what already exists (read-only)"
sudo -v || die "sudo is required. Run this from an administrator account."
id "$CONTROLLER_USER" >/dev/null 2>&1 || die "No account '$CONTROLLER_USER'."
id "$WORKER_USER" >/dev/null 2>&1 || die "No account '$WORKER_USER'. This wizard never creates accounts."
CHOME=$(getent passwd "$CONTROLLER_USER" | cut -d: -f6); WHOME=$(getent passwd "$WORKER_USER" | cut -d: -f6)
KEY="$CHOME/.ssh/$KEY_NAME"; PUB="$KEY.pub"
GATE="$BIN_DIR/commonroom-ssh-gate"; WORKER="$BIN_DIR/commonroom-worker"
say "Controller account : $CONTROLLER_USER ($CHOME)"
say "Worker account     : $WORKER_USER ($WHOME)"
for f in "$GATE" "$WORKER"; do
  if sudo -u "$WORKER_USER" test -x "$f"; then say "Executable by $WORKER_USER : $f"; else die "$f is missing or not executable by $WORKER_USER."; fi
done
sudo test -e "$KEY" && say "Controller key     : exists ($KEY)" || say "Controller key     : absent"
sudo test -d "$WHOME/.ssh" && say "Worker .ssh dir     : $(sudo stat -c '%U:%G %a' "$WHOME/.ssh")" || say "Worker .ssh dir     : absent"
if sudo test -e "$WHOME/.ssh/authorized_keys"; then
  say "Worker authorized_keys: $(sudo grep -c . "$WHOME/.ssh/authorized_keys") line(s); entries mentioning the gate: $(sudo grep -c 'commonroom-ssh-gate' "$WHOME/.ssh/authorized_keys" || true)"
else say "Worker authorized_keys: absent"; fi
sudo test -e "$CHOME/.ssh/config" && say "Controller ssh config has alias '$ALIAS': $(sudo grep -c "^Host $ALIAS\$" "$CHOME/.ssh/config" || true) time(s)" || say "Controller ssh config: absent"
SSHD=$(sudo sshd -T 2>/dev/null | grep -E '^(allowusers|allowgroups|denyusers|pubkeyauthentication|passwordauthentication|permitopen|maxsessions) ' || true)
[[ -n "$SSHD" ]] && printf '%s\n' "$SSHD" | sed 's/^/      sshd: /'
if printf '%s\n' "$SSHD" | grep -qiE '^(allowusers|allowgroups)'; then
  warn "sshd restricts users/groups; make sure $WORKER_USER (from 127.0.0.1) is permitted."
fi
ss -ltn 2>/dev/null | grep -q ':22 ' && say "sshd listening on port 22" || warn "Nothing is listening on port 22."
pause "Review the above, then press Enter to continue (Ctrl-C to stop)"

# ── Stage 2: controller key ──────────────────────────────────────────────
stage "Controller SSH key"
if sudo test -e "$KEY"; then
  note "ok:      $KEY exists; it will not be replaced"
else
  say "Creates an unencrypted ed25519 key for $CONTROLLER_USER. It can only run the gate (see stage 3), but protect it like a credential."
  if confirm "Create $KEY?"; then
    run as_controller mkdir -p -m 700 "$CHOME/.ssh"
    run as_controller ssh-keygen -q -t ed25519 -N '' -C "$KEY_NAME" -f "$KEY"
  else SKIPPED+=("controller key not created"); fi
fi
if (( DRY )) && ! sudo test -e "$PUB"; then
  PUBKEY="ssh-ed25519 AAAA...dry-run-placeholder $KEY_NAME"
else
  PUBKEY=$(sudo cat "$PUB" 2>/dev/null) || die "No public key at $PUB."
fi
say "Public key: ${PUBKEY:0:60}..."
pause

# ── Stage 3: authorize the key for the gate only ─────────────────────────
stage "Authorize the key on $WORKER_USER (forced command, no shell)"
LINE="command=\"$GATE --worker $WORKER\",restrict $PUBKEY"
printf '%s\n' "$LINE" > "$TMP/line"
say "Line to install:"; note "$LINE"
KEYBODY=$(printf '%s' "$PUBKEY" | awk '{print $2}')
if ! sudo test -d "$WHOME/.ssh"; then
  confirm "Create $WHOME/.ssh (700, owned by $WORKER_USER)?" && run sudo install -d -o "$WORKER_USER" -g "$(id -gn "$WORKER_USER")" -m 700 "$WHOME/.ssh" || SKIPPED+=("worker .ssh not created")
fi
AK="$WHOME/.ssh/authorized_keys"
if sudo test -e "$AK" && sudo grep -qF "$KEYBODY" "$AK"; then
  CURRENT=$(sudo grep -F "$KEYBODY" "$AK")
  if [[ "$CURRENT" == "$LINE" ]]; then
    note "ok:      the key is already authorized with exactly these options"
  else
    warn "The key is already authorized with different options (- current, + proposed):"
    { diff -u <(printf '%s\n' "$CURRENT") "$TMP/line" || true; } | sed 's/^/      /'
    if confirm "Replace that line? A timestamped backup is kept."; then
      run sudo cp -p "$AK" "$AK.bak.$(date +%Y%m%d%H%M%S)"
      if (( ! DRY )); then
        sudo grep -vF "$KEYBODY" "$AK" > "$TMP/ak.new" || true
        cat "$TMP/line" >> "$TMP/ak.new"
        sudo install -o "$WORKER_USER" -g "$(id -gn "$WORKER_USER")" -m 600 "$TMP/ak.new" "$AK"
      else note "would replace the line for this key"; fi
    else SKIPPED+=("authorized_keys line left unchanged"); fi
  fi
else
  if confirm "Append the line to $AK?"; then
    if (( ! DRY )); then
      if sudo test -e "$AK"; then sudo cp -p "$AK" "$AK.bak.$(date +%Y%m%d%H%M%S)"; sudo cat "$AK" > "$TMP/ak.new"; else : > "$TMP/ak.new"; fi
      cat "$TMP/line" >> "$TMP/ak.new"
      sudo install -o "$WORKER_USER" -g "$(id -gn "$WORKER_USER")" -m 600 "$TMP/ak.new" "$AK"
      note "wrote:   $AK"
    else note "would append the line to $AK"; fi
  else SKIPPED+=("key not authorized"); fi
fi
pause

# ── Stage 4: host key and controller ssh config ──────────────────────────
stage "Pin the host key and add the alias '$ALIAS'"
HOSTPUB=/etc/ssh/ssh_host_ed25519_key.pub
[[ -r "$HOSTPUB" ]] || die "Cannot read $HOSTPUB."
EXPECTED=$(ssh-keygen -lf "$HOSTPUB" | awk '{print $2}')
say "Host key fingerprint on disk: $EXPECTED"
KH="$CHOME/.ssh/known_hosts"
if sudo test -e "$KH" && as_controller ssh-keygen -F "$HOST" -f "$KH" >/dev/null 2>&1; then
  note "ok:      $HOST already has a known_hosts entry (not changed)"
else
  ssh-keyscan -t ed25519 "$HOST" 2>/dev/null > "$TMP/scanned"
  SCANNED=$(ssh-keygen -lf "$TMP/scanned" | awk '{print $2}')
  if [[ -n "$SCANNED" && "$SCANNED" == "$EXPECTED" ]]; then
    note "fingerprint from the network matches the key on disk"
    confirm "Add $HOST to $KH?" && { run sudo -u "$CONTROLLER_USER" tee -a "$KH" < "$TMP/scanned" >/dev/null; } || SKIPPED+=("host key not pinned")
  else
    die "Fingerprint mismatch (disk $EXPECTED, network ${SCANNED:-none}). Not pinning."
  fi
fi
cat > "$TMP/hostblock" <<EOT
Host $ALIAS
  HostName $HOST
  User $WORKER_USER
  IdentityFile $KEY
  IdentitiesOnly yes
  BatchMode yes
  StrictHostKeyChecking yes
EOT
CFG="$CHOME/.ssh/config"
if sudo test -e "$CFG" && sudo grep -q "^Host $ALIAS\$" "$CFG"; then
  note "ok:      alias '$ALIAS' already exists in $CFG (not changed; check it matches):"
  sudo awk -v a="$ALIAS" '$1=="Host"{p=($2==a)} p' "$CFG" | sed 's/^/      /'
else
  say "Block to append to $CFG:"; sed 's/^/      /' "$TMP/hostblock"
  if confirm "Append it?"; then
    if (( ! DRY )); then
      sudo test -e "$CFG" && sudo cp -p "$CFG" "$CFG.bak.$(date +%Y%m%d%H%M%S)"
      { sudo test -e "$CFG" && sudo cat "$CFG"; printf '\n'; cat "$TMP/hostblock"; } > "$TMP/cfg.new" || true
      sudo install -o "$CONTROLLER_USER" -g "$(id -gn "$CONTROLLER_USER")" -m 600 "$TMP/cfg.new" "$CFG"
      note "wrote:   $CFG"
    else note "would append the block to $CFG"; fi
  else SKIPPED+=("ssh alias not added"); fi
fi
pause

# ── Stage 5: verify end to end ───────────────────────────────────────────
stage "Verify as $CONTROLLER_USER"
if (( DRY )); then
  note "dry run: skipping the live checks"
else
  say "1. An allowed action (ready-v1) must return the worker's JSON:"
  as_controller ssh -T "$ALIAS" "exec ~/.local/bin/commonroom-worker ready-v1" </dev/null && note "ok" || warn "ready-v1 failed (see the message above)"
  say "2. A plain command must be refused:"
  # Capture first: under pipefail a refused command's nonzero exit would fail a pipeline.
  refusal=$(as_controller ssh -T "$ALIAS" id </dev/null 2>&1 || true)
  if [[ "$refusal" == *"Forbidden worker command"* ]]; then note "ok: refused"; else warn "NOT refused as expected; remove the authorized_keys line and investigate"; fi
fi
say ""
say "Controller service environment (edit your environment file, then restart the service):"
note "COMMONROOM_SERVER_WORKER=false"
note "COMMONROOM_REMOTE_WORKER=true"
note "COMMONROOM_REMOTE_WORKER_ALIAS=$ALIAS"
note "Register the connection with endpoint ssh://$ALIAS (Claude: ssh://$ALIAS/claude)."

finish
}

run_wizard "$@"; exit
